using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class SceneTabsOperations
{
    public Button new_tab_choice(string label,string description){var button=new Button{Text=label+"\n"+description,Alignment=HorizontalAlignment.Left,CustomMinimumSize=new Vector2(0,58)};button.AddThemeStyleboxOverride("normal",tab_style(new Color("172633"),new Color("334e62")));button.AddThemeStyleboxOverride("hover",tab_style(new Color("235045"),new Color("68ddc4")));return button;}
    public void show_new_tab_menu(TabBar owner){owner.Set("_switching",true);owner.CurrentTab=Math.Max(0,Active(owner));owner.Set("_switching",false);var popup=new PopupPanel();owner.AddChild(popup);popup.AddThemeStyleboxOverride("panel",tab_style(new Color("101a24"),new Color("48657a")));var column=new VBoxContainer{CustomMinimumSize=new Vector2(320,0)};column.AddThemeConstantOverride("separation",8);popup.AddChild(column);var title=new Label{Text="CREATE NEW TAB"};title.AddThemeColorOverride("font_color",new Color("74dec7"));column.AddChild(title);var choices=new (string Label,string Description,Action Create)[]{("▣  Scene","Edit actors, animation, timeline, and export",()=>new_scene(owner)),("◆  Shader Editor","Write shaders with a live mesh and environment preview",()=>new_shader(owner)),("▣  Image Editor","Draw, crop, transform, and save project images",()=>new_image(owner)),("♫  Audio Workspace","Edit waveforms, arrange music, record, mix, and export",()=>new_audio(owner)),("◇  3D Modeling","Create and edit mesh geometry, components, and modifiers",()=>new_model(owner)),("△  Environment Creator","Create terrains, landscapes, structures, natural environments, and procedural worlds.",()=>new_environment(owner)),("◈  Transformation Image 2D","Draw independent states, morph, and animate components",()=>new_transformation(owner)),("▧  Compositing","Layer footage, images, and graphics with a shared image engine",()=>new_composition(owner))};foreach(var entry in choices){var button=new_tab_choice(entry.Label,entry.Description);column.AddChild(button);button.Pressed+=()=>{popup.QueueFree();entry.Create();};}popup.PopupHide+=popup.QueueFree;popup.PopupCentered(new Vector2I(430,600));}
    public void filesystem_resource_opened(TabBar owner,string path){string extension=path.GetExtension().ToLowerInvariant();var audio=GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_workspace.gd").GetScriptConstantMap()["AUDIO_EXTENSIONS"].AsStringArray();if(audio.Contains(extension)){open_audio(owner,path,new Settings());return;}var image=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_workspace.gd").GetScriptConstantMap()["IMAGE_EXTENSIONS"].AsStringArray();if(image.Contains(extension)){open_simple_workspace(owner,"image",path);return;}if(extension is not ("tres" or "res"))return;var resource=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);if(ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_scene_data.gd"))open_scene(owner,path);else if(ActorDataOperations.ScriptIs(resource,"res://Workspaces/AudioWorkspace/KiwiAudioDocument.cs"))open_audio(owner,path,new Settings());else if(ActorDataOperations.ScriptIs(resource,"res://Workspaces/ImageWorkspace/image_document.gd"))open_simple_workspace(owner,"image",path);else if(ActorDataOperations.ScriptIs(resource,"res://Workspaces/EnvironmentWorkspace/environment_document.gd"))open_simple_workspace(owner,"environment",path);else if(ActorDataOperations.ScriptIs(resource,"res://Workspaces/ModelWorkspace/model_document.gd"))open_simple_workspace(owner,"model",path);else if(ActorDataOperations.ScriptIs(resource,"res://Workspaces/TransformationWorkspace/transformation_document.gd"))open_transformation(owner,path);else if(resource is CompositingDocument||ActorDataOperations.ScriptIs(resource,"res://Workspaces/CompositingWorkspace/compositing_document.gd"))open_simple_workspace(owner,"compositing",path);}
    public void workspace_asset_to_scene(TabBar owner,string kind,string path){capture_current(owner);int found=-1;for(int i=Documents(owner).Count-1;i>=0;i--)if(Kind(Documents(owner)[i].AsGodotDictionary())=="scene"){found=i;break;}if(found>=0)open_index(owner,found);else new_scene(owner);var timeline=Timeline(owner);if(timeline==null)return;var model=timeline.Get("model").As<RefCounted>();var definition=_definitions.get_definition(timeline.Get("registry").As<RefCounted>(),kind=="model"?"basic_mesh":"environment_asset");if(definition!=null)_timeline.create_actor(model,definition,timeline.Get("canvas").As<Control>().Get("playhead").AsDouble(),new Settings{[new StringName(kind=="model"?"mesh_path":"environment_path")]=path});}
}
